export interface CarMedia {
  mediaId: string;
  base64: string;
  mimeType: string;
  name: string;
}

export type GenerationStatus = 'idle' | 'generating' | 'success' | 'error';

export type CompositionType = 'Confrontation' | 'Parallel' | 'Perspective' | 'Dynamic';

import React from 'react';
import { CarMedia } from '../types';

interface CarSlotProps {
  label: string;
  media: CarMedia | null;
  onSelect: () => void;
  onClear: () => void;
}

export const CarSlot: React.FC<CarSlotProps> = ({ label, media, onSelect, onClear }) => {
  return (
    <div className="group relative w-full aspect-video bg-[#1a1a1a] border border-[#595959] hover:border-[#7a7a7a] rounded-xl overflow-hidden transition-colors cursor-pointer" onClick={media ? undefined : onSelect}>
      {media ? (
        <>
          <img 
            src={`data:${media.mimeType};base64,${media.base64}`} 
            alt={label} 
            className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity"
          />
          <div className="absolute top-2 right-2 flex gap-1">
            <button 
              onClick={(e) => { e.stopPropagation(); onClear(); }}
              className="w-7 h-7 bg-black/60 backdrop-blur-md border border-white/10 rounded-full flex items-center justify-center text-white hover:bg-black/80 transition-colors"
            >
              <span className="material-symbols-outlined text-[16px]">close</span>
            </button>
          </div>
        </>
      ) : (
        <div className="w-full h-full flex flex-col items-center justify-center gap-2 text-[rgba(218,220,224,0.5)]">
          <span className="material-symbols-outlined text-[32px]">directions_car</span>
          <span className="text-[11px] font-medium tracking-[0.1px] uppercase">Select {label}</span>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { CarMedia, GenerationStatus, CompositionType } from './types';
import { CarSlot } from './components/CarSlot';

// UI Primitives
const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

const SegmentedToggle: React.FC<{
  value: string; items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent">
    {items.map((item) => (
      <button key={item.value} type="button" onClick={() => onChange(item.value)}
        className={`flex-1 flex items-center justify-center gap-1 h-[34px] px-2 py-2 rounded-xl text-[10px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
          value === item.value ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
        }`}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

const RangeSlider: React.FC<{
  label: string; value: number; min: number; max: number;
  step?: number; formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-2 pt-2 pb-[5px] w-full">
    <div className="flex items-center justify-between px-2 select-none">
      <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-[#c7c9cd] tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="px-2 w-full flex items-center h-2">
      <input type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => onChange(Number(e.target.value))} 
        className="w-full"
      />
    </div>
  </div>
);

// New Orbital POV Selector
const POVCompass: React.FC<{ value: number; onChange: (v: number) => void }> = ({ value, onChange }) => {
  const points = [
    { deg: 0, label: 'B', name: 'Back' },
    { deg: 45, label: 'BR', name: 'Rear-Right' },
    { deg: 90, label: 'R', name: 'Right Side' },
    { deg: 135, label: 'FR', name: 'Front-Right' },
    { deg: 180, label: 'F', name: 'Front' },
    { deg: 225, label: 'FL', name: 'Front-Left' },
    { deg: 270, label: 'L', name: 'Left Side' },
    { deg: 315, label: 'BL', name: 'Rear-Left' },
  ];

  return (
    <div className="relative w-full aspect-square p-2 bg-white/5 border border-[#595959] rounded-xl flex items-center justify-center">
      <div className="absolute inset-0 flex items-center justify-center opacity-10 pointer-events-none">
        <div className="w-[70%] h-[70%] border border-dashed border-white rounded-full" />
      </div>

      {/* Center Showdown Icon */}
      <div className="z-0 opacity-20 flex flex-col items-center">
         <span className="material-symbols-outlined text-[20px]">swords</span>
      </div>

      {points.map((p, i) => {
        const rad = (p.deg - 90) * (Math.PI / 180);
        const radius = 38; // percentage
        const x = 50 + radius * Math.cos(rad);
        const y = 50 + radius * Math.sin(rad);

        return (
          <button
            key={i}
            onClick={() => onChange(p.deg)}
            className={`absolute w-8 h-8 -translate-x-1/2 -translate-y-1/2 rounded-full border flex items-center justify-center transition-all duration-300 ${
              value === p.deg 
                ? 'bg-white border-white text-black scale-110 shadow-[0_0_15px_rgba(255,255,255,0.3)] z-10' 
                : 'bg-[#1a1a1a] border-white/10 text-white/40 hover:border-white/40'
            }`}
            style={{ left: `${x}%`, top: `${y}%` }}
          >
            <span className="text-[9px] font-bold">{p.label}</span>
          </button>
        );
      })}
    </div>
  );
};

const CarGrid: React.FC<{
  pos1: number; pos2: number;
  dir1: number; dir2: number;
  activeCar: 1 | 2;
  onPosChange: (slot: 1 | 2, pos: number) => void;
  onDirToggle: (slot: 1 | 2) => void;
}> = ({ pos1, pos2, dir1, dir2, activeCar, onPosChange, onDirToggle }) => {
  return (
    <div className="grid grid-cols-3 gap-1 w-full aspect-square p-2 bg-white/5 border border-[#595959] rounded-xl overflow-hidden">
      {Array.from({ length: 9 }).map((_, i) => {
        const isCar1 = pos1 === i;
        const isCar2 = pos2 === i;
        const isActive = (activeCar === 1 && isCar1) || (activeCar === 2 && isCar2);

        return (
          <button
            key={i}
            onClick={() => {
              if (isCar1) onDirToggle(1);
              else if (isCar2) onDirToggle(2);
              else onPosChange(activeCar, i);
            }}
            className={`relative flex items-center justify-center rounded-lg border transition-all duration-200 ${
              isCar1 ? 'bg-blue-500 border-blue-400 z-10' : 
              isCar2 ? 'bg-orange-500 border-orange-400 z-10' : 
              'bg-transparent border-white/5 hover:bg-white/5'
            } ${isActive ? 'ring-2 ring-white ring-offset-2 ring-offset-[#1a1a1a]' : ''}`}
          >
            {isCar1 && (
              <div className="flex flex-col items-center transition-transform duration-300" style={{ transform: `rotate(${dir1}deg)` }}>
                <span className="material-symbols-outlined text-[18px] text-white">navigation</span>
                <span className="text-[8px] font-bold text-white leading-none -mt-1" style={{ transform: `rotate(-${dir1}deg)` }}>1</span>
              </div>
            )}
            {isCar2 && (
              <div className="flex flex-col items-center transition-transform duration-300" style={{ transform: `rotate(${dir2}deg)` }}>
                <span className="material-symbols-outlined text-[18px] text-white">navigation</span>
                <span className="text-[8px] font-bold text-white leading-none -mt-1" style={{ transform: `rotate(-${dir2}deg)` }}>2</span>
              </div>
            )}
          </button>
        );
      })}
    </div>
  );
};

export default function App() {
  const [car1, setCar1] = useState<CarMedia | null>(null);
  const [car2, setCar2] = useState<CarMedia | null>(null);

  // Selection
  const [activeCar, setActiveCar] = useState<1 | 2>(1);

  // Camera Orbit (Compass)
  const [cameraOrbit, setCameraOrbit] = useState(180); // Default: Front view
  const [tilt, setTilt] = useState('High');
  const [lens, setLens] = useState('Wide');

  // Arrangement
  const [car1Pos, setCar1Pos] = useState(3);
  const [car2Pos, setCar2Pos] = useState(5);
  const [car1Dir, setCar1Dir] = useState(180);
  const [car2Dir, setCar2Dir] = useState(180);
  const [composition, setComposition] = useState<CompositionType>('Confrontation');

  const handlePosChange = (slot: 1 | 2, pos: number) => {
    if (slot === 1) {
      if (pos === car2Pos) setCar2Pos(car1Pos);
      setCar1Pos(pos);
    } else {
      if (pos === car1Pos) setCar1Pos(car2Pos);
      setCar2Pos(pos);
    }
  };

  const handleDirToggle = (slot: 1 | 2) => {
    const current = slot === 1 ? car1Dir : car2Dir;
    const next = (current + 45) % 360;
    if (slot === 1) setCar1Dir(next);
    else setCar2Dir(next);
  };

  // Environment & Lighting
  const [background, setBackground] = useState('Studio');
  const [timeOfDay, setTimeOfDay] = useState('Day');
  const [lightAngle, setLightAngle] = useState(45);
  const [neonIntensity, setNeonIntensity] = useState(0);

  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [result, setResult] = useState<{ base64: string; mimeType: string } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif; letter-spacing: 0.1px; -webkit-font-smoothing: antialiased; }
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; }
      .animate-shimmer { background: linear-gradient(90deg, transparent, rgba(255,255,255,0.05), transparent); background-size: 200% 100%; animation: shimmer 2s infinite linear; }
      @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
      .custom-scrollbar::-webkit-scrollbar { width: 4px; }
      .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .custom-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 10px; }
    `;
    document.head.appendChild(style);
  }, []);

  const getPoseDescription = (deg: number) => {
    if (deg === 0) return "facing straight ahead (tail-lights towards camera)";
    if (deg === 45) return "angled 45 degrees, showing the rear-right quarter";
    if (deg === 90) return "parked in right profile, side-on";
    if (deg === 135) return "angled 135 degrees, showing the front-right quarter";
    if (deg === 180) return "parked front-on, headlights facing the camera";
    if (deg === 225) return "angled 225 degrees, showing the front-left quarter";
    if (deg === 270) return "parked in left profile, side-on";
    if (deg === 315) return "angled 315 degrees, showing the rear-left quarter";
    return `facing ${deg} degrees`;
  };

  const getPOVDescription = (deg: number) => {
    if (deg === 180) return "from a Direct Frontal POV, looking straight at the confrontation";
    if (deg === 135) return "from a Front-Right Three-Quarter POV, observing at an angle";
    if (deg === 90) return "from a Right Profile POV, viewing the cars from the side";
    if (deg === 45) return "from a Rear-Right Three-Quarter POV, watching from behind-right";
    if (deg === 0) return "from a Direct Rear POV, looking at the backs of the vehicles";
    if (deg === 315) return "from a Rear-Left Three-Quarter POV, watching from behind-left";
    if (deg === 270) return "from a Left Profile POV, viewing the cars from the side";
    if (deg === 225) return "from a Front-Left Three-Quarter POV, observing at an angle";
    return `from a ${deg} degree orbital POV`;
  };

  const handleSelectCar = async (slot: 1 | 2) => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      const carData: CarMedia = {
        mediaId: media.mediaId,
        base64: media.base64,
        mimeType: media.mimeType,
        name: media.name
      };
      if (slot === 1) setCar1(carData);
      else setCar2(carData);
    } catch (e) {
      console.error('Selection cancelled');
    }
  };

  const generateShowdown = async () => {
    if (!car1 || !car2) return;
    setStatus('generating');
    setError(null);

    const posNames = ["top-left", "top-center", "top-right", "middle-left", "middle-center", "middle-right", "bottom-left", "bottom-center", "bottom-right"];

    const prompt = `Cinematic ${lens} lens masterwork photography of two custom vehicles in a ${composition.toLowerCase()} face-off.

      Camera Orchestration:
      - Point of View: Viewed ${getPOVDescription(cameraOrbit)} at a ${tilt} elevation.
      - Lens: ${lens === 'Fish' ? 'extreme fish-eye lens with distortion' : lens === 'Wide' ? 'cinematic wide-angle lens' : 'standard 50mm portrait lens'} with shallow depth of field.

      Staging & Blocking:
      - Arrangement style: ${composition}.
      - Car 1: Placed in the ${posNames[car1Pos]} region of the frame, ${getPoseDescription(car1Dir)}.
      - Car 2: Placed in the ${posNames[car2Pos]} region of the frame, ${getPoseDescription(car2Dir)}.

      Environmental & Light:
      - Setting: ${background} environment.
      - Lighting: ${timeOfDay} setup. Light rays coming from a ${lightAngle} degree angle, catching the metallic paint and glass perfectly.
      ${neonIntensity > 0 ? `- Style: Volumetric lighting with ${neonIntensity}% saturated neon underglow and sharp rim-lighting.` : ''}

      Technical:
      - Exact visual consistency for both car references. High-fidelity textures and physically based rendering.
      - Dramatic, professional automotive photography composition.`;

    try {
      const result = await Flow.generate.image({
        prompt,
        referenceImageMediaIds: [car1.mediaId, car2.mediaId],
        modelDisplayName: '🍌 Nano Banana Pro',
        aspectRatio: '16:9'
      });

      setResult({ base64: result.base64, mimeType: result.mimeType });
      setStatus('success');
    } catch (err: any) {
      setError(err?.message || 'Generation failed.');
      setStatus('error');
    }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">
      <div className="relative border-r border-white/10 flex flex-col items-start justify-between px-3 py-4 w-[340px] h-full bg-[#0e0e0e] shrink-0">
        <div className="flex flex-col gap-6 items-start w-full overflow-y-auto custom-scrollbar pr-1">

          <div className="flex flex-col gap-2 w-full">
            <SectionLabel>1. References</SectionLabel>
            <div className="flex gap-1.5 w-full">
              <CarSlot label="Car 1" media={car1} onSelect={() => handleSelectCar(1)} onClear={() => setCar1(null)} />
              <CarSlot label="Car 2" media={car2} onSelect={() => handleSelectCar(2)} onClear={() => setCar2(null)} />
            </div>
          </div>

          <div className="flex flex-col gap-2 w-full">
            <SectionLabel>2. Composition Style</SectionLabel>
            <div className="grid grid-cols-2 gap-1 w-full">
              {(['Confrontation', 'Parallel', 'Perspective', 'Dynamic'] as CompositionType[]).map(type => (
                <button
                  key={type}
                  onClick={() => setComposition(type)}
                  className={`px-2 py-2 rounded-xl text-[10px] font-medium border transition-all ${composition === type ? 'bg-white border-white text-black shadow-[0_0_10px_rgba(255,255,255,0.1)]' : 'border-[#595959] text-white/60 hover:border-white/40'}`}
                >
                  {type}
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col gap-2 w-full">
            <SectionLabel>3. Orbital Camera (POV)</SectionLabel>
            <div className="flex gap-3 items-center">
              <div className="w-28 shrink-0">
                 <POVCompass value={cameraOrbit} onChange={setCameraOrbit} />
              </div>
              <div className="flex-1 flex flex-col gap-2">
                 <SegmentedToggle 
                    value={tilt} 
                    onChange={setTilt}
                    items={[
                      { value: 'Low', label: 'Low' },
                      { value: 'Eye', label: 'Eye' },
                      { value: 'High', label: 'High' },
                    ]}
                  />
                  <SegmentedToggle 
                    value={lens} 
                    onChange={setLens}
                    items={[
                      { value: 'Fish', label: 'Fish' },
                      { value: 'Wide', label: 'Wide' },
                      { value: 'Normal', label: 'Norm' },
                    ]}
                  />
                  <p className="text-[9px] text-white/40 leading-tight pl-1">
                    POV: {getPOVDescription(cameraOrbit).replace('from a ', '')}
                  </p>
              </div>
            </div>
          </div>

          <div className="flex flex-col gap-2 w-full">
            <SectionLabel>4. Grid Arrangement</SectionLabel>
            <div className="flex flex-col gap-2 w-full">
              <SegmentedToggle 
                value={activeCar.toString()} 
                onChange={(v) => setActiveCar(parseInt(v) as 1 | 2)}
                items={[
                  { value: '1', label: 'Edit Car 1', icon: <span className="material-symbols-outlined text-[16px] text-blue-400">edit_square</span> },
                  { value: '2', label: 'Edit Car 2', icon: <span className="material-symbols-outlined text-[16px] text-orange-400">edit_square</span> },
                ]}
              />
              <div className="flex gap-3 items-center">
                <div className="w-28 shrink-0">
                  <CarGrid 
                    pos1={car1Pos} pos2={car2Pos} 
                    dir1={car1Dir} dir2={car2Dir} 
                    activeCar={activeCar}
                    onPosChange={handlePosChange}
                    onDirToggle={handleDirToggle}
                  />
                </div>
                <div className="flex-1 flex flex-col gap-3">
                  <RangeSlider 
                    label="Rotation" 
                    value={activeCar === 1 ? car1Dir : car2Dir} 
                    min={0} 
                    max={315} 
                    step={45} 
                    formatValue={(v) => `${v}°`} 
                    onChange={(v) => activeCar === 1 ? setCar1Dir(v) : setCar2Dir(v)} 
                  />
                  <p className="text-[9px] text-white/40 leading-tight">
                    {getPoseDescription(activeCar === 1 ? car1Dir : car2Dir)}
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="flex flex-col gap-2 w-full">
            <SectionLabel>5. Environment</SectionLabel>
            <div className="grid grid-cols-3 gap-1 w-full">
              {['Studio', 'Nature', 'Stone', 'Asphalt', 'Driving', 'Water'].map(env => (
                <button
                  key={env}
                  onClick={() => setBackground(env)}
                  className={`px-2 py-1.5 rounded-lg text-[9px] font-medium border transition-all ${background === env ? 'bg-[#969696] border-[#969696] text-black' : 'border-[#595959] text-white/60 hover:bg-white/5'}`}
                >
                  {env}
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col gap-3 w-full pb-4">
            <SectionLabel>6. Lighting & FX</SectionLabel>
            <div className="flex gap-1.5 w-full">
              <SegmentedToggle 
                value={timeOfDay} 
                onChange={setTimeOfDay}
                items={[
                  { value: 'Day', label: 'Day' },
                  { value: 'Night', label: 'Night' },
                  { value: 'Sunset', label: 'Sunset' },
                ]}
              />
            </div>
            <RangeSlider label="Light Angle" value={lightAngle} min={0} max={360} formatValue={(v) => `${v}°`} onChange={setLightAngle} />
            <RangeSlider label="Neon Intensity" value={neonIntensity} min={0} max={100} formatValue={(v) => v === 0 ? 'Off' : `${v}%`} onChange={setNeonIntensity} />
          </div>

          {error && <p className="text-red-400 text-[10px] px-2">{error}</p>}
        </div>

        <div className="w-full pt-4 border-t border-white/5 bg-[#0e0e0e]">
          <PillButton 
            variant="solid" 
            disabled={!car1 || !car2 || status === 'generating'}
            onClick={generateShowdown}
            icon={status === 'generating' ? null : <span className="material-symbols-outlined text-[18px]">auto_awesome</span>}
          >
            {status === 'generating' ? 'Rendering Scene...' : 'Render Selection'}
          </PillButton>
        </div>
      </div>

      <div className="flex-1 relative flex items-center justify-center p-8 bg-[#0a0a0a]">
        {status === 'generating' ? (
          <div className="w-full max-w-4xl aspect-video rounded-2xl overflow-hidden animate-shimmer bg-white/5 flex flex-col items-center justify-center gap-4">
            <div className="w-10 h-10 rounded-full border-2 border-white/20 border-t-white animate-spin" />
            <p className="text-white/60 text-sm font-medium tracking-wide uppercase">Compositing Arena</p>
          </div>
        ) : result ? (
          <div className="relative group max-w-full max-h-full">
            <img src={`data:${result.mimeType};base64,${result.base64}`} alt="Result" className="max-w-full max-h-[85vh] rounded-2xl shadow-2xl border border-white/10 object-contain" />
            <button 
              onClick={() => Flow.download({ ...result, filename: `car_arrangement_${Date.now()}.jpg` })}
              className="absolute top-4 right-4 h-10 px-4 bg-black/60 backdrop-blur-md border border-white/10 rounded-xl flex items-center gap-2 hover:bg-black/80 transition-all opacity-0 group-hover:opacity-100"
            >
              <span className="material-symbols-outlined text-[20px]">download</span>
              <span className="text-xs font-medium">Export</span>
            </button>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-4 opacity-10">
            <span className="material-symbols-outlined text-[120px]">photo_camera_back</span>
            <p className="text-xl font-medium tracking-tight">Stage your showdown</p>
          </div>
        )}
      </div>
    </div>
  );
}
